// TH18 v1.00a th18_s2_b5: st02bs.ecl.txt Boss3 (330-370) -> BossCard3 (696-843).
// Card source t0 = Boss3 entry; BossCard3 entry = source t160; attack t120 later.
const TIME_LIMIT: int = 2682;   // 120 buffer + 160 prelude + 2400 source spell + 2
const SOURCE_LIMIT: int = 2400; // source setInterrupt(0,0,2400,"BossDead")

// Source BossCard3_at EX list:
//   slot0 ANIM a=1 (birth retreat 4*speed, handled at fire position),
//   slot1 OFFSCREEN 600, slot2 VELADD(900,-9999994,%B,1.0),
//   slot3 ANGLE_ACCEL(900,-9999994,0.0,%C, async=1).
// VELADD is a fixed per-frame displacement vector e; ANGLE_ACCEL rotates the base
// velocity by w each frame.  Keep the exact cartesian sum u(t)+e with a per-frame
// CART acceleration g=(R-I)(v-e):  c1=cos(w)-1, sn=sin(w), k=(R-I)e.
xformdef SPIRAL(c1: fx, sn: fx, kx: fx, ky: fx) {
    offscreen_keep(600);
again:
    set_gravity(
        at_effect(c1*$self_vx - sn*$self_vy - kx),
        at_effect(sn*$self_vx + c1*$self_vy - ky));
    wait(1);
    loop(again, 900);
    set_gravity(0fx, 0fx);
}

// One source @BossCard3_at(...) async: one shared et slot, 8 etOn shots of N
// fan bullets every 5 frames, then one big bullet 20 frames later.
async sub cluster(center: angle, drift: angle, n: int) {
    var ex: fx = cos(drift);
    var ey: fx = sin(drift);
    var c1: fx = cos(drift)-1fx;
    var sn: fx = sin(drift);
    var kx: fx = c1*ex - sn*ey;
    var ky: fx = sn*ex + c1*ey;
    for shot in 0..8 {
        // etAim(id,1) fixed fan: F(N,i)=(-1)^i*H(N,i), loop etAngle delta=0.5235988 rad=5461 BAM.
        for i in 0..n {
            var off: int = 0;
            if n % 2 == 0 {
                off = (i/2)*5461 + 2731;      // even N: (floor(i/2)+1/2)*delta
            } else {
                off = ((i+1)/2)*5461;         // odd N: floor((i+1)/2)*delta
            }
            if i % 2 != 0 { off = -off; }
            var base: angle = center + (off as angle);
            var vx: fx = 3fx*cos(base) + ex;  // source etSpeed 3.0 + VELADD 1.0
            var vy: fx = 3fx*sin(base) + ey;
            var sp: fx = dist(vx, vy);
            var ang: angle = atan2(vy, vx);
            // ANIM a=1: position -= 4*velocity (12 px back along the configured angle).
            _ = fire(TH18_DROPLET, 10,
                     $self_x - 12fx*cos(base), $self_y - 12fx*sin(base),
                     sp, ang, SPIRAL(c1, sn, kx, ky), none);
        }
        wait(5);
    }
    wait(20);
    // etNew(9): type19 color5, aim mode1 count1, angle %B, speed 1, ANIM a=1 retreat 4.
    _ = fire(TH18_BIG_BALL2, 5,
             $self_x - 4fx*cos(drift), $self_y - 4fx*sin(drift),
             1fx, drift, none, none);
}

async sub pattern() {
    wait(120); // training opening buffer; Boss3 source t0 follows
    // Boss3: movePosTime(90,9,0,128), wait(160).  Independent entry is (0,128),
    // so the return-to-centre move is zero displacement; its time still elapses.
    move_to(90, 0fx, 128fx, EASE_QUAD_IN_OUT);
    wait(160);
    // BossCard3 entry: setInterrupt(0,0,2400,"BossDead"); spell declaration.
    set_self_int(1, $frame+SOURCE_LIMIT);
    set_self_int(0, 60);
    set_self_fx(0, 0fx);
    set_self_fx(1, 0fx);
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    wait(60); // source +120 attack start
    var n: int = 3;
    var interval: int = 20;
    var rank: int = global(GVAR_RANK);
    if rank == 0 { interval = 40; } // source !E wait(40); N/H/L wait(20)
    if rank == 2 { n = 4; }
    if rank == 3 { n = 5; }
    var b: angle = 728bam; // 0.069813 rad; flips after each source async call
    var a: angle = aim_player();
    // First source half-cycle: A=ANGLE_PLAYER, +45deg per call, no moveRand yet.
    for c1 in 0..8 {
        spawn cluster(a+90deg, b, n);
        a = a+45deg;
        b = (0-(b as int)) as angle;
        wait(interval);
    }
    loop {
        // Source moveRand(60,4,1.0) at each half-cycle boundary.
        card_move_rand();
        a = aim_player();
        // Second half-cycle: A=ANGLE_PLAYER, -45deg per call.
        for c2 in 0..8 {
            if $frame >= self_int(1) { return; }
            spawn cluster(a+90deg, b, n);
            a = a-45deg;
            b = (0-(b as int)) as angle;
            card_wait(interval);
        }
        if $frame >= self_int(1) { return; }
        card_move_rand();
        a = aim_player();
        // First half-cycle again: +45deg per call.
        for c3 in 0..8 {
            if $frame >= self_int(1) { return; }
            spawn cluster(a+90deg, b, n);
            a = a+45deg;
            b = (0-(b as int)) as angle;
            card_wait(interval);
        }
        if $frame >= self_int(1) { return; }
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);  // source Boss() setHitbox(48,48): ordinary circle half-width
    set_hurtbox(20fx); // source Boss() setHurtbox(40,40): half-width
    spell_begin(0, 16, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 2700, 0, 0, 0, boss_main);
    loop { wait(600); }
}

// TH18 v1.00a BossCard3 moveRand(60,4,1.0) with moveLimit(0,144,128,64).
// int0 = next source movement step, int1 = source spell end frame; fx0/1 = logical unit vector.
// Source 405b90 = signed unit random * pi; unwrapped BAM ints below.
// Every source wait after the first moveRand must use card_wait(n) in the same owner task.
sub card_arm_next_step() {
    var k: int = self_int(0)+1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = 1.0fx*((60-k) as fx)/60fx; }
    var nx: fx = $self_x + self_fx(0)*speed;
    var ny: fx = $self_y + self_fx(1)*speed;
    if nx < -64fx { nx = -64fx; }
    if nx > 64fx { nx = 64fx; }
    if ny < 112fx { ny = 112fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
}
sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}
sub card_move_rand() {
    var r: int = rand(65536)-32768;
    var a: int = r/3;
    if $self_x < -32fx {
        a = r/3;
    } else if $self_x > 32fx {
        a = r/3+32768;
        if a > 32768 { a = a-65536; } // source explicitly normalizes this branch
    } else {
        a = r/4;
        var choose: int = rand(65536)%3; // source WORD modulo3, including its tiny bias
        if $player_x > $self_x {
            if choose == 0 { a = a+32768; }
        } else {
            if choose != 0 { a = a+32768; }
        }
        // Deliberately do not normalize this branch before the source fabs tests.
    }
    if $self_y < 128fx {
        if a < 0 { a = -a; }
    } else if $self_y > 160fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05 rad. Nearest BAM boundaries (normal quantization).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= self_int(1) { move_vel(0, 0deg, 0fx, EASE_LINEAR); return; }
        card_arm_next_step();
    }
}

